const http = require('http');
const { WebSocket } = require('ws');

function get(path) {
  return new Promise((resolve, reject) => {
    http.get({ host: 'localhost', port: 9222, path, headers: { Accept: 'application/json' } }, res => {
      let d = ''; res.on('data', c => d += c); res.on('end', () => resolve(d));
    }).on('error', reject);
  });
}

async function main() {
  const list = JSON.parse(await get('/json/list'));
  const target = list.find(t => t.type === 'page');
  if (!target) throw new Error('no page target');
  const wsUrl = target.webSocketDebuggerUrl;
  console.log('connecting', wsUrl);
  const ws = new WebSocket(wsUrl);
  await new Promise(r => ws.once('open', r));
  let id = 0;
  const send = (method, params) => {
    const msg = { id: ++id, method, params: params || {} };
    return new Promise((resolve, reject) => {
      ws.send(JSON.stringify(msg));
      ws.once('message', data => {
        const parsed = JSON.parse(data.toString());
        if (parsed.id === msg.id) {
          if (parsed.error) reject(parsed.error);
          else resolve(parsed.result);
        }
      });
    });
  };
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Input.enable');

  // Press space to start
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: ' ', windowsVirtualKeyCode: 32, code: 'Space' });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: ' ', windowsVirtualKeyCode: 32, code: 'Space' });
  await new Promise(r => setTimeout(r, 300));

  // Play for ~2.5 seconds: hold right + jump periodically
  const end = Date.now() + 2500;
  let lastJump = 0;
  while (Date.now() < end) {
    const now = Date.now();
    if (now - lastJump > 700) {
      await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowUp', windowsVirtualKeyCode: 38, code: 'ArrowUp' });
      await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowUp', windowsVirtualKeyCode: 38, code: 'ArrowUp' });
      lastJump = now;
    }
    await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowRight', windowsVirtualKeyCode: 39, code: 'ArrowRight' });
    await new Promise(r => setTimeout(r, 50));
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowRight', windowsVirtualKeyCode: 39, code: 'ArrowRight' });
    await new Promise(r => setTimeout(r, 50));
  }

  const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 85 });
  require('fs').writeFileSync('/home/runner/work/PlayGround/PlayGround/screenshots/gameplay.jpg', Buffer.from(shot.data, 'base64'));
  console.log('saved screenshot');
  ws.close();
  process.exit(0);
}
main().catch(e => { console.error(e); process.exit(1); });

