const http = require('http');
const fs = require('fs');

function get(path) {
  return new Promise((resolve, reject) => {
    http.get({ host: 'localhost', port: 9222, path, headers: { Accept: 'application/json' } }, res => {
      let d = ''; res.on('data', c => d += c); res.on('end', () => resolve(d));
    }).on('error', reject);
  });
}

async function main() {
  const list = JSON.parse(await get('/json/list'));
  const target = list.find(t => t.type === 'page');
  if (!target) throw new Error('no page target');
  console.log('connecting', target.webSocketDebuggerUrl);
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise(r => ws.addEventListener('open', r, { once: true }));
  let id = 0;
  const pending = new Map();
  ws.addEventListener('message', ev => {
    const parsed = JSON.parse(ev.data.toString());
    if (typeof parsed.id === 'number' && pending.has(parsed.id)) {
      const { resolve, reject } = pending.get(parsed.id);
      pending.delete(parsed.id);
      if (parsed.error) reject(parsed.error); else resolve(parsed.result);
    }
  });
  const send = (method, params) => {
    const msg = { id: ++id, method, params: params || {} };
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify(msg));
    });
  };
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Input.enable');

  const key = (k, code, vk) => {
    return send('Input.dispatchKeyEvent', { type: 'keyDown', key: k, windowsVirtualKeyCode: vk, code })
      .then(() => new Promise(r => setTimeout(r, 25)))
      .then(() => send('Input.dispatchKeyEvent', { type: 'keyUp', key: k, windowsVirtualKeyCode: vk, code }));
  };

  await key(' ', 'Space', 32);
  await new Promise(r => setTimeout(r, 300));

  const end = Date.now() + 2500;
  let lastJump = 0;
  while (Date.now() < end) {
    const now = Date.now();
    if (now - lastJump > 700) { await key('ArrowUp', 'ArrowUp', 38); lastJump = now; }
    await send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowRight', windowsVirtualKeyCode: 39, code: 'ArrowRight' });
    await new Promise(r => setTimeout(r, 50));
    await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowRight', windowsVirtualKeyCode: 39, code: 'ArrowRight' });
    await new Promise(r => setTimeout(r, 50));
  }

  const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 85 });
  fs.writeFileSync('/home/runner/work/PlayGround/PlayGround/screenshots/gameplay.jpg', Buffer.from(shot.data, 'base64'));
  console.log('saved screenshot');
  ws.close();
  process.exit(0);
}
main().catch(e => { console.error(e); process.exit(1); });

